-- KZ: one shared catalog records the official region of every guardian.
BEGIN;
ALTER TABLE public.kz_guardian_catalog ADD COLUMN IF NOT EXISTS region_id smallint;
UPDATE public.kz_guardian_catalog
SET region_id=CASE
  WHEN guardian_id BETWEEN 2000 AND 6999 THEN 0
  WHEN guardian_id BETWEEN 7000 AND 8999 THEN 1
  WHEN guardian_id BETWEEN 9000 AND 9699 THEN 2
  WHEN guardian_id BETWEEN 9700 AND 10399 THEN 3
  WHEN guardian_id BETWEEN 10400 AND 11099 THEN 4
  WHEN guardian_id BETWEEN 11100 AND 11799 THEN 5
  WHEN guardian_id BETWEEN 11800 AND 12499 THEN 6
  WHEN guardian_id BETWEEN 12500 AND 13199 THEN 7
  ELSE region_id END WHERE kind='iron';
